StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						Statistics
//	CREATOR:					Helgevold - Daniel Årvik
// REQUIREMENTS: 		NX CPU
// 
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	VERSION			DATE					SIGN						DESCRIPTION
//	1.0.0					2023-02-01			Daniel Årvik				Initial release
// 2.0.0					2025-04-02			William Veim			ReWork
// 2.0.1					2025-09-09			William Veim			Translation
// 2.0.2					2026-03-21			William Veim			Bugfix reset data
//
//================================================================================================================================
//
//		BESKRIVELSE:
//		Registrerer driftstimer og resetdato basert på total reset og service reset.
//		Registrerer også antall starter siden total reset.
//
//================================================================================================================================

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

Current_Time := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
Current_Date := DT_TO_DATE(GetTime());
Current_TimeStamp :=CONCAT(In1:=CONCAT(In1:=DateToString(Current_Date), In2:=' '), In2:=DELETE(In:=TODToString(Current_TIME), L:=13, P:=6));

//Initialising reset date
IF Out_ResetDate_Service = ''  AND Inp_Feedback THEN
	Out_ResetDate_Service := Current_TimeStamp;
END_IF;

IF Out_ResetDate_Total = '' AND Inp_Feedback THEN
	Out_ResetDate_Total := Current_TimeStamp;
END_IF;

(*************************************************************************
 *	STATISTICS
 *************************************************************************)

//Running input adds tast time to total time
IF Inp_Feedback THEN
	
Out_RunTime_Total := ADD_TIME(In1:=Out_RunTime_Total, In2:=GetMyTaskInterval());
Out_RunTime_Service := ADD_TIME(In1:=Out_RunTime_Service, In2:=GetMyTaskInterval());

END_IF;

//Increment number of start 
RE_Running(Clk:=Inp_Feedback);

IF RE_Running.Q THEN
	Inc(Out_NumOfStarts);
END_IF;

(*************************************************************************
 *	RESET DATA
 *************************************************************************)

// Setter dato for service til dagens dato om Reset_Service går høy
IF Inp_Reset_Service OR Inp_Reset_Total THEN
	Out_RunTime_Service := TIME#0s;
	Out_ResetDate_Service := Current_TimeStamp;
	Inp_Reset_Service:=FALSE;
END_IF;

// Setter dato for total resett til dagens dato om Reset_Total går høy
IF Inp_Reset_Total THEN
	Out_RunTime_Total := TIME#0s;
	Out_NumOfStarts := 0;
	Out_ResetDate_Total := Current_TimeStamp;
	Inp_Reset_Total:=FALSE;
END_IF;
